<?php
declare(strict_types=1);
require __DIR__ . '/Cdp.php';
$credentials = json_decode(file_get_contents($argv[1] ?? '/tmp/iscrizioni-browser/credentials.json'), true, 16, JSON_THROW_ON_ERROR);
$curl = curl_init('http://127.0.0.1:9222/json/new?http://127.0.0.1:5173/index.php');
curl_setopt_array($curl, [CURLOPT_CUSTOMREQUEST => 'PUT', CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 10]);
$page = json_decode(curl_exec($curl), true, 32, JSON_THROW_ON_ERROR); curl_close($curl);
$browser = new Cdp($page['webSocketDebuggerUrl']);
$browser->call('Runtime.enable');
$browser->call('Page.enable');
$browser->call('Emulation.setDeviceMetricsOverride', ['width' => 1680, 'height' => 1050, 'deviceScaleFactor' => 1, 'mobile' => false]);
$browser->wait('document.querySelector("input[name=password]") !== null');
$browser->evaluate('document.querySelector("input[name=username]").value=' . json_encode($credentials['username']) . ';document.querySelector("input[name=password]").value=' . json_encode($credentials['password']) . ';document.querySelector("form").requestSubmit();true');
$browser->wait('document.querySelectorAll("tbody tr").length >= 2');
$version = $browser->evaluate('React.version');
if ($version !== '18.3.1') throw new RuntimeException('Versione React errata.');
echo "PASS: Login nel browser e rendering React $version.\n";
$browser->wait('document.querySelector("tr[data-event-id=\"http-test\"]").innerText.includes("42 (importato)")');
echo "PASS: Colonna iscrizioni di ieri con conteggio giornaliero importato.\n";
$browser->evaluate('(()=>{const input=document.querySelector("input[aria-label=\"Nome nuovo evento\"]");Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set.call(input,"Evento React senza JSON");input.dispatchEvent(new Event("input",{bubbles:true}));return true;})()');
$browser->evaluate('document.querySelector("input[aria-label=\"Nome nuovo evento\"]").form.requestSubmit();true');
$browser->wait('Array.from(document.querySelectorAll("tbody tr")).some(row=>row.innerText.includes("Evento React senza JSON"))');
echo "PASS: Creazione evento senza JSON tramite interfaccia React.\n";
$browser->evaluate('document.querySelector("tr[data-event-id=pisa] button").click();true');
$browser->evaluate('(()=>{const input=document.querySelector("input[type=date]");Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set.call(input,"2026-11-04");input.dispatchEvent(new Event("input",{bubbles:true}));input.dispatchEvent(new Event("change",{bubbles:true}));return true;})()');
$browser->wait('Array.from(document.querySelectorAll("button")).some(b=>b.innerText === "Usa storico Pisa 2025")');
$browser->evaluate('Array.from(document.querySelectorAll("button")).find(b=>b.innerText === "Usa storico Pisa 2025").click();true');
$browser->wait('document.querySelector("tr[data-event-id=pisa]").innerText.includes("2025-11-02")');
echo "PASS: Importazione storico Pisa e confronto settimanale nella stessa riga.\n";
$yesterday = (new DateTimeImmutable('now', new DateTimeZone('Europe/Rome')))->modify('-1 day')->format('Y-m-d');
$beforeYesterday = (new DateTimeImmutable('now', new DateTimeZone('Europe/Rome')))->modify('-2 days')->format('Y-m-d');
$browser->evaluate('(()=>{const input=document.querySelector("input[type=date]");Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set.call(input,' . json_encode($yesterday) . ');input.dispatchEvent(new Event("input",{bubbles:true}));input.dispatchEvent(new Event("change",{bubbles:true}));return true;})()');
$browser->wait('document.querySelector("tr[data-event-id=\"http-test\"]").innerText.includes(' . json_encode($beforeYesterday) . ')');
echo "PASS: Iscrizioni di ieri seguono la data selezionata.\n";
$browser->evaluate('Array.from(document.querySelectorAll("button")).find(b=>b.innerText === "Oggi").click();true');
$browser->wait('document.querySelector("tr[data-event-id=\"http-test\"]").innerText.includes("42 (importato)")');
$browser->call('Page.reload', ['ignoreCache' => true]);
$browser->wait('Array.from(document.querySelectorAll("tbody tr")).some(row=>row.innerText.includes("Evento React senza JSON"))');
echo "PASS: Eventi persistenti dopo ricaricamento.\n";
$directory = dirname(__DIR__, 2) . '/exports'; if (!is_dir($directory)) mkdir($directory, 0700, true);
$image = $browser->call('Page.captureScreenshot', ['format' => 'png', 'captureBeyondViewport' => false]);
file_put_contents($directory . '/dashboard-php-react.png', base64_decode($image['data']));
$browser->call('Emulation.setDeviceMetricsOverride', ['width' => 390, 'height' => 844, 'deviceScaleFactor' => 1, 'mobile' => true]);
$browser->wait('document.querySelector("table") !== null');
if (!$browser->evaluate('document.querySelector(".event-table-wrap").scrollWidth > document.querySelector(".event-table-wrap").clientWidth')) throw new RuntimeException('Tabella mobile non scorrevole.');
$image = $browser->call('Page.captureScreenshot', ['format' => 'png', 'captureBeyondViewport' => false]);
file_put_contents($directory . '/dashboard-php-react-mobile.png', base64_decode($image['data']));
echo "PASS: Righe singole e scorrimento orizzontale su mobile.\n";
if ($browser->errors) throw new RuntimeException('Errori JavaScript: ' . json_encode($browser->errors));
echo "PASS: Nessuna eccezione JavaScript nel browser.\n";
